javascript.solution:
function rateFor(table, tiv) {
  let lo = 0;
  let hi = table.length - 1;
  let ans = -1;
  while (lo <= hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (table[mid][0] <= tiv) {
      ans = table[mid][1];     // candidate; maybe a higher band also fits
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return ans;
}
